class Solution {
public:
    int minCostToEqualizeArray(vector<int>& nums, int cost1, int cost2) {
        const long long MOD = 1e9 + 7;
        int n = nums.size();
        if (n == 1) return 0;
        int mx = *max_element(nums.begin(), nums.end());
        priority_queue<int> pq;
        for (int x : nums) pq.push(mx - x);
        long long cost = 0;
        while (pq.top() > 0) {
            int a = pq.top(); pq.pop();
            if ((long long)cost2 < 2LL * cost1 && !pq.empty() && pq.top() > 0) {
                int b = pq.top(); pq.pop();
                pq.push(b - 1);
                cost += cost2;
            } else cost += cost1;
            pq.push(a - 1);
        }
        return cost % MOD;
    }
};

