class Solution {
    public int minCostToEqualizeArray(int[] nums, int cost1, int cost2) {
        final long MOD = 1_000_000_007L;
        int n = nums.length;
        if (n == 1) return 0;
        int mx = Arrays.stream(nums).max().getAsInt();
        PriorityQueue<Integer> pq = new PriorityQueue<>(Collections.reverseOrder());
        for (int x : nums) pq.add(mx - x);
        long cost = 0;
        while (pq.peek() > 0) {
            int a = pq.poll();
            if (cost2 < 2 * cost1 && !pq.isEmpty() && pq.peek() > 0) {
                int b = pq.poll();
                pq.add(b - 1);
                cost += cost2;
            } else cost += cost1;
            pq.add(a - 1);
        }
        return (int) (cost % MOD);
    }
}

