var minCostToEqualizeArray = function(nums, cost1, cost2) {
    const MOD = 1e9 + 7, n = nums.length;
    if (n === 1) return 0;
    const mx = Math.max(...nums);
    const a = nums.map(x => mx - x).sort((x, y) => y - x);
    let cost = 0;
    while (a[0] > 0) {
        if (cost2 < 2 * cost1 && n > 1 && a[1] > 0) {
            a[1]--; cost += cost2;
        } else cost += cost1;
        a[0]--;
        let i = 0;
        while (i + 1 < n && a[i] < a[i + 1]) { [a[i], a[i + 1]] = [a[i + 1], a[i]]; i++; }
    }
    return cost % MOD;
};

