class Solution {
public:
    int minCostToEqualizeArray(vector<int>& nums, int cost1, int cost2) {
        const long long MOD = 1e9 + 7;
        int n = nums.size();
        if (n == 1) return 0;
        long long mx = *max_element(nums.begin(), nums.end());
        long long mn = *min_element(nums.begin(), nums.end());
        long long S = 0;
        for (int x : nums) S += mx - x;
        long long Mx = mx - mn;
        long long best = LLONG_MAX;
        long long hi = (cost2 < 2LL * cost1) ? 2 * Mx + 2 : 0;
        for (long long d = 0; d <= hi; d++) {
            long long tot = S + n * d, M = Mx + d;
            long long p = (cost2 < 2LL * cost1) ? min(tot / 2, tot - M) : 0;
            long long c = tot * cost1 - p * (2LL * cost1 - cost2);
            best = min(best, c);
        }
        return best % MOD;
    }
};

