var minCostToEqualizeArray = function(nums, cost1, cost2) {
    const MOD = 1e9 + 7, n = nums.length;
    if (n === 1) return 0;
    const mx = Math.max(...nums), mn = Math.min(...nums);
    let S = 0;
    for (const x of nums) S += mx - x;
    const Mx = mx - mn;
    const mul = (a, b) => { a %= MOD; b %= MOD; let r = 0;
        while (b > 0) { if (b & 1) r = (r + a) % MOD; a = (a * 2) % MOD; b >>>= 1; } return r; };
    let best = Infinity;
    const hi = cost2 < 2 * cost1 ? 2 * Mx + 2 : 0;
    for (let d = 0; d <= hi; d++) {
        const tot = S + n * d, M = Mx + d;
        const p = cost2 < 2 * cost1 ? Math.min(Math.floor(tot / 2), tot - M) : 0;
        const c = (mul(tot, cost1) - mul(p, (2 * cost1 - cost2) % MOD) + MOD) % MOD;
        if (c < best) best = c;
    }
    return best;
};
